INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'realite', 'realite', 'Talents de Réalité', '122 talents achetés en XP : Origine, Sphère, communs, expertises (lot 14).', '{"nature":"realite","lecture":"- **Origine** : le milieu d''où vient le personnage. Le talent est **conservé** même si la Sphère change.\n- **Sphère** : le système auquel il appartient maintenant (Corporatiste, Gouvernementale, Mafieuse, Religieuse, Crawler). Un talent de Sphère peut **disparaître** si le personnage perd réellement son statut, son emploi ou son appartenance.\n- **Communs** et **expertises** : ouverts à tous.\n- **Carte courte** : ce qui suit. **Texte de référence** : celui du site, inchangé. Les quotas « par scène » ou « par scénario » sont ceux du texte de référence.\n- Un talent de **Contact** donne une personne nommée, réelle, avec ses moyens et ses limites, sans bonus chiffré.\n\n---","equipement":"Pas de réécriture : profils, prix et architecture sont fermés (annexe C, §12 à §19), et l''extraction du site ne porte souvent que le nom et une ligne. Le texte de référence est celui des documents Réalité V1 finaux du 8 septembre et du site.\n\n**Corrections appliquées** :\n1. **FaceCaster DFL** : il apparaît deux fois (#61 et #145, même objet, deux descriptions). On garde #61, qui a le texte le plus complet ; #145 devient un renvoi. Doublon exact.\n2. **Paires Gen1 / Gen2** : 35 augmentations ont deux entrées du même nom, une par génération, mais sans étiquette. Dans 11 paires, le texte est même identique (Ports d''interface, Audiovox, Cyberbras, Cyberjambe, Pistolet intégré, Lame cachée, Griffes / ongles, Poings renforcés, Grappin, Jambes renforcées, Palmes cybernétiques). Chaque entrée reçoit l''étiquette **Gen1** ou **Gen2**. Quand les deux générations ont le même effet, la carte le dit : « Gen1 = Gen2 ». Les identifiants restent tous. *Exemple* : Booster d''adrénaline, Gen2 +1 PA pendant 1 round puis +1 Stress temporaire ; Gen1 +1 PA pendant 2 rounds puis +2 Stress temporaire (annexe C §12.6).\n3. **Notes de développement** : les mentions « ‖ Usage réel selon description ; pas de bonus… » et « ‖ Fonction matérielle conforme au texte… » sont des garde-fous du moteur. Elles sortent du texte joueur et passent au niveau de référence (rapport 02, B9, compatible avec la décision 1).\n4. **Abréviations d''armure** : « Bal. », « Mel. », « Ant. » s''écrivent en toutes lettres (Balistique, Mêlée, Antichoc) sur les cartes. Les valeurs et la règle de cumul ne changent pas.\n\n**Présentation seule (aucun chiffre ne bouge)** :\n- les neuroprogrammes qui forment une gamme (D-Fence, MyWall, Castland) sont présentés côte à côte (rapport 02, B8, sans la variante « Épines », qui ajoutait une règle) ;\n- les lots de munitions standard (#244 à #261) sont regroupés en un tableau fabricant × calibre.\n\n---","corrections":"1. **Notes de développement retirées du texte joueur** (75 talents). Les formules du type « ‖ Droit, relation, prestation ou possession réelle : vérifier existence… », « préparé », « realityDailyRecovery », « permitsSurprisedDefense », « bareHandDamage » sont des notes de moteur. Elles restent dans le registre comme référence technique, jamais sur la carte.\n2. **Aucun autre changement.** Les 55 talents de l''annexe J sont déjà à jour. Les 67 autres sont gardés tels quels, y compris les talents de ressource sans chiffre (Compte de frais, Service juridique, Planque, Blanchiment, Faussaires, Entreprise de couverture, Soutien communautaire, Logifake, Fixweb, Corruption locale). Leur mesure est fictionnelle, et c''est voulu (§10.1 : ne pas les surnaturaliser ni les chiffrer d''office).\n\n---","cout_xp":10}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
