INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'procedures_administratives', 'Procédures administratives', NULL, '{"nature":"realite","categorie":"origin","milieu":"gouvernementale","cout_xp":10,"texte_court":"1/scénario : un recours suspend jusqu''à la fin de la scène l''exécution d''une décision administrative contre toi ou ton client. Ni annulation ni effet sur un danger immédiat.","texte_reference":"Une fois par scénario, lorsqu’une institution s’apprête à exécuter une décision administrative contre vous ou une personne que vous représentez, vous pouvez exploiter une procédure recevable pour en suspendre l’exécution jusqu’à la fin de la scène, le temps d’un réexamen. Il ne faut pas réussir un second jet pour obtenir ce délai. La suspension peut retarder une saisie, une fermeture, un transfert administratif ou une expulsion ; elle ne désarme pas une intervention face à un danger immédiat. La décision n’est pas annulée : vous disposez d’une fenêtre réelle pour agir, négocier ou apporter une pièce nouvelle.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
