INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'dossier_propre', 'Dossier propre', NULL, '{"nature":"realite","categorie":"origin","milieu":"gouvernementale","cout_xp":10,"texte_court":"Aux contrôles de routine, tes pièces suffisent : pas de fouille ni de retenue sur un simple soupçon. Une preuve ou un mandat permettent toujours l''enquête.","texte_reference":"Votre identité civile réelle bénéficie d’un crédit de confiance renforcé. Aux contrôles de routine, lorsque votre Logifate et vos pièces correspondent à la situation, leur vérification suffit : pas de fouille approfondie, de retenue ou d’exigence d’un garant provoquées uniquement par un soupçon vague. Le talent vous fait aussi reconnaître comme client ou visiteur fiable dans les démarches ordinaires, sans garantie de faveur financière. Une preuve directe, un mandat ciblé, un objet interdit visible ou une contradiction concrète permettent une investigation normale. Aucun document absent ni fausse identité n’est créé.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'codes_du_milieu', 'Codes du milieu', NULL, '{"nature":"realite","categorie":"origin","milieu":"mafieuse","cout_xp":10,"texte_court":"+2 Diplomatie sur les rites, rangs, tabous et manières de parler de ta Pègre d''origine.","texte_reference":"+2 Diplomatie pour connaître respect, rites, rangs, tabous et façons correctes de parler dans sa Pègre d’origine.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'omerta_familiale', 'Omerta familiale', NULL, '{"nature":"realite","categorie":"origin","milieu":"mafieuse","cout_xp":10,"texte_court":"+2 Force Mentale contre une pression profane pour te faire trahir ta famille ; 1/scène, relance d''une résistance ratée. +4 au total avec Omerta.","texte_reference":"Vous bénéficiez de +2 Force Mentale contre les pressions et intimidations profanes visant directement à vous faire trahir votre famille ou votre ancien milieu. Une fois par scène, vous pouvez relancer une résistance ratée dans ce cadre, hors échec narratif ; vous conservez le second résultat. Le talent protège votre résistance personnelle, pas vos proches eux-mêmes, et ne masque pas vos souvenirs à une lecture mentale directe. Lorsque le même test relève également d’Omerta, leurs deux bonus se cumulent exceptionnellement pour +4, sans troisième bonus équivalent ni deuxième relance de talent.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
