INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'education_caritative', 'Éducation caritative', NULL, '{"nature":"realite","categorie":"origin","milieu":"religieuse","cout_xp":10,"texte_court":"+2 Soin, Diplomatie ou Savoirs (au choix) en situation d''assistance sociale.","texte_reference":"+2 Soin, Diplomatie ou Savoirs, choisi à la création, dans les situations d’assistance sociale correspondant réellement à son éducation.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'debrouille', 'Débrouille', NULL, '{"nature":"realite","categorie":"origin","milieu":"crawler","cout_xp":10,"texte_court":"+1 Survie en milieu pauvre ou hors système ; tu compenses jusqu''à −3 de matériel absent ou médiocre par des substituts réels.","texte_reference":"Vous conservez +1 Survie dans les milieux urbains pauvres, abandonnés ou hors système. Pour une tâche non offensive dont vous connaissez la méthode, vous pouvez compenser jusqu’à −3 de malus provenant d’un matériel courant absent ou médiocre en employant des substituts réellement disponibles. Vous ne fabriquez pas un composant indispensable et ne remplacez pas une expertise que vous ne possédez pas.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'codes_de_rue', 'Codes de rue', NULL, '{"nature":"realite","categorie":"origin","milieu":"crawler","cout_xp":10,"texte_court":"+2 Langages & Argot pour l''argot, les signes et les codes Underlives.","texte_reference":"+2 Langages & Argot pour argot, signes, graffitis et codes Underlives.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'enfant_des_zones_mortes', 'Enfant des zones mortes', NULL, '{"nature":"realite","categorie":"origin","milieu":"crawler","cout_xp":10,"texte_court":"+3 pour circuler et t''orienter dans ton ancien quartier abandonné.","texte_reference":"Circonstance favorable (+3) pour circuler et s’orienter dans son ancien quartier abandonné.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'on_connait_quelquun', 'On connaît quelqu’un', NULL, '{"nature":"realite","categorie":"origin","milieu":"crawler","cout_xp":10,"texte_court":"Un Contact mineur Crawler.","texte_reference":"Un Contact mineur Crawler.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'recuperateur', 'Récupérateur', NULL, '{"nature":"realite","categorie":"origin","milieu":"crawler","cout_xp":10,"texte_court":"+2 Investigation pour trouver de l''utile dans des ruines, des déchets techniques ou des squats.","texte_reference":"+2 Investigation lorsqu’il s’agit de trouver quelque chose d’utile dans des ruines, déchets techniques, squats ou infrastructures abandonnées.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'dotation_standard', 'Dotation standard', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Un lot d''équipement de poste en plus, jusqu''à 5 000 $, entretenu par l''employeur. Ni véhicule ni augmentation ; non revendable.","texte_reference":"Votre employeur vous confie un lot spécialisé supplémentaire, choisi dans l’équipement autorisé et utile à votre poste, jusqu’à 5 000 $ de valeur catalogue. Il en assure l’entretien courant et le remplacement d’usure. Ce lot s’ajoute aux outils indispensables déjà fournis par le poste ; il ne finance ni véhicule ni augmentation. Il reste propriété de l’employeur et n’est pas revendable. Une perte opérationnelle est traitée par le service, pas remplacée instantanément.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'assurance_corporative', 'Assurance corporative', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"1/scénario, la corporation répare ou remplace un bien professionnel désigné (gamme équivalente). Pas de couverture rétroactive.","texte_reference":"La corporation garantit un bien professionnel non unique que vous possédez réellement, inscrit sur la fiche : arme, armure, appareil, augmentation ou véhicule. Une fois par scénario, elle finance sa remise en état après des dommages opérationnels, ou son remplacement à fonction et gamme équivalentes s’il est détruit ou irrécupérable. L’intervention est engagée sans avance de frais, avec le délai matériel ou médical nécessaire. L’objet couvert peut être changé entre deux scénarios, avant les dommages ; il ne peut être assuré rétroactivement. Aucune amélioration de gamme, duplication après récupération de l’original ou destruction volontaire destinée à encaisser une indemnité n’est couverte.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'badge_interne', 'Badge interne', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Accès confidentiel aux sites secrets d''un programme ou d''une branche choisie, sans escorte. Ni commandement ni dossiers d''office.","texte_reference":"Vous détenez une accréditation confidentielle réelle au sein de votre corporation. Elle ouvre les sites sécurisés et secrets d’un programme ou d’une branche sensible choisis : laboratoire clandestin, centre d’essai, dépôt protégé ou installation analogue. La sécurité reconnaît votre droit d’entrer et de circuler sans escorte dans ce périmètre ; aucune nouvelle faveur n’est à négocier à chaque visite. Les sites appartenant au même périmètre sont couverts. L’accès physique ne donne ni commandement, ni contrôle universel des systèmes, ni extraction automatique de tous les dossiers compartimentés.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'avantages_salaries', 'Avantages salariés', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Un second Appui de Sphère (par exemple logement **et** véhicule de fonction).","texte_reference":"Votre contrat prend en charge un deuxième Appui de Sphère corporatif, choisi selon les mêmes catégories, niveaux et limites que l’appui initial. Vous pouvez ainsi disposer d’un logement ET d’un véhicule de fonction, au lieu d’un seul avantage. Les deux prestations existent simultanément et leur prise en charge est inscrite sur la fiche. La même prestation ne peut être comptée deux fois. Ce talent n’ajoute pas d’argent au Compte et ne transfère pas la propriété des biens qui restent sous contrat.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'compte_de_frais', 'Compte de frais', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Dépenses professionnelles raisonnables prises en charge.","texte_reference":"Dépenses professionnelles raisonnables prises en charge.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'reseau_interne', 'Réseau interne', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Un Contact dans un autre service de la corporation.","texte_reference":"Un Contact dans un autre service de la corporation.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'profil_calibre', 'Profil calibré', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"1/scénario, relance d''un échec non narratif dans une Compétence professionnelle choisie.","texte_reference":"Votre corporation vous a spécialement formé pour une Compétence professionnelle de votre Style, choisie et inscrite à l’acquisition. Une fois par scénario, après un échec non narratif à un test de cette Compétence dans une tâche correspondant à votre métier, vous pouvez relancer le 1d10e et conserver le second résultat. Le coût de l’action n’est pas payé une seconde fois et aucun PA n’est créé. Les conditions de formation nécessaires restent applicables ; ce talent n’est pas un point permanent de Compétence.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'acces_fournisseur', 'Accès fournisseur', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Stocks professionnels de la corporation ; −10 % sur le catalogue (hors prototypes, pièces uniques, médical, revente). Se cumule avec Maître du Troc.","texte_reference":"Vous accédez directement aux stocks professionnels ordinaires de votre corporation et de ses partenaires désignés, avec réservation et délai annoncé. Vos achats personnels ou professionnels autorisés bénéficient de 10 % de réduction sur le prix catalogue, hors prototypes, pièces uniques et prestations médicales. Cette réduction ne se cumule pas avec une autre remise de statut de même nature : retenir la meilleure. Elle ne s’applique pas aux acquisitions destinées à la revente. Les 5 points de pourcentage de Maître du Troc et le résultat d’une négociation s’ajoutent à cet avantage de statut.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'service_juridique', 'Service juridique', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Assistance légale dans les affaires qui relèvent du travail.","texte_reference":"Assistance légale dans les affaires relevant réellement du travail.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'programme_pilote', 'Programme pilote', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"Un prototype prêté, au choix : +2 à une fonction précise, ou un appareil portable sans Encombrant, ou une nouvelle fonction validée. Fixé avant l''acquisition.","texte_reference":"Vous recevez un prototype professionnel réellement jouable, construit sur un équipement de Réalité autorisé par votre fonction. Avant l’acquisition, sa fiche fixe le modèle de base, une amélioration expérimentale exclusive, ses valeurs, ses limites et ses conditions d’entretien. L’amélioration peut être un bonus de +2 à une fonction précisément définie, la suppression de la propriété Encombrant d’un appareil portable compatible, ou une nouvelle fonction concrète validée par le MJ. Ces options sont alternatives, pas cumulées. Le +2 remplace un éventuel bonus équivalent inférieur de la version standard. Un seul prototype est prêté à la fois, sans achat du matériel ; il reste propriété de la corporation. Il peut être remplacé entre deux missions par un autre essai du programme préalablement défini, jamais reconfiguré librement en pleine scène.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'extraction_corporative', 'Extraction corporative', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"1/scénario, une extraction prioritaire est engagée (rendez-vous, capacité, délai annoncés). Elle n''est pas instantanée.","texte_reference":"Une fois par scénario, dans le périmètre réel d’intervention de l’employeur, vous pouvez déclencher une extraction prioritaire. L’autorisation interne est acquise : un moyen de récupération est engagé, avec rendez-vous, capacité et délai annoncés. Il peut emporter vos compagnons dans sa capacité réelle. Vous devez transmettre votre position et rejoindre ou ouvrir un accès praticable. Le talent garantit la mobilisation, pas une arrivée instantanée ni le franchissement automatique d’un blocus.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'requin_corporatif', 'Requin corporatif', NULL, '{"nature":"realite","categorie":"sphere","milieu":"corporatiste","cout_xp":10,"texte_court":"+2 Diplomatie ou Commerce (au choix) dans les négociations entre corporations.","texte_reference":"+2 Diplomatie ou Commerce, choisi à l’acquisition, lors de négociations professionnelles entre corporations.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'dotation_de_service', 'Dotation de service', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"Un kit en plus, jusqu''à 5 000 $, échangeable au dépôt entre deux missions. Ni véhicule ni augmentation.","texte_reference":"Le service vous attribue un kit supplémentaire, jusqu’à 5 000 $ d’équipement autorisé par votre fonction, au-delà de votre matériel indispensable. Ce kit peut être échangé au dépôt entre deux missions pour une autre configuration de même plafond ; entretien courant et usure sont pris en charge. Armes, véhicules et augmentations restent soumis à leurs accès propres ; ce lot ne finance ni véhicule ni augmentation. Le matériel doit être restitué et ne peut être vendu.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'habilitation_administrative', 'Habilitation administrative', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"Accès aux sites secrets d''un secteur gouvernemental choisi. Les fichiers relèvent d''Accès aux registres.","texte_reference":"Vous possédez une habilitation réelle d’accès aux sites secrets d’un secteur gouvernemental choisi : installations de renseignement, centres techniques protégés, dépôts sécurisés ou établissements analogues. Un contrôle régulier confirme votre autorisation d’y entrer et de circuler dans les zones couvertes, sans demander une faveur au responsable. Le secteur peut regrouper plusieurs sites pertinents. Cette habilitation n’accorde ni commandement, ni accès universel aux fichiers des personnes présentes : les données confidentielles relèvent d’Accès aux registres.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'reseau_administratif', 'Réseau administratif', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"Un Contact dans un autre service public.","texte_reference":"Un Contact dans un autre service public.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'acces_aux_registres', 'Accès aux registres', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"Droit de consultation d''une catégorie de données confidentielles choisie (police, médical, Logifate…). L''historique des accès reste.","texte_reference":"Choisissez une grande catégorie de données confidentielles : dossiers de police et enquêtes, dossiers médicaux institutionnels, Logifate et historiques administratifs, ou une catégorie comparable pertinente. Vous disposez d’un droit réel de consultation et de recoupement de cette catégorie, y compris hors du besoin ordinaire de votre poste. La consultation d’un dossier identifié ne demande pas un nouveau jet de négociation ; les recherches complexes et l’interprétation peuvent demander Investigation ou Savoirs. L’accès peut passer par un terminal habilité ou une interface sécurisée. Les données inexistantes, détruites ou exceptionnellement compartimentées hors de l’habilitation restent inaccessibles ; l’historique des accès n’est pas supprimé.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'procedure_acceleree', 'Procédure accélérée', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"+2 pour faire avancer une démarche de ton domaine ; 1/scénario, une autorisation provisoire immédiate, régularisée après.","texte_reference":"Vous conservez +2 aux tests visant à faire progresser une démarche de votre domaine. Une fois par scénario, vous pouvez obtenir une autorisation provisoire exécutoire immédiatement après un échange avec le service, les validations et formalités détaillées étant régularisées après l’opération. Cela peut permettre le transport d’un témoin, l’usage d’un moyen ordinaire ou une intervention recevable sans attendre le circuit complet. Le service doit avoir compétence pour autoriser l’acte ; le talent ne crée pas une ressource et ne remplace ni une accréditation secrète ni une décision formellement interdite.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'fonctionnaire_experimente', 'Fonctionnaire expérimenté', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"+1 Diplomatie avec l''administration ; 1 fois par démarche, réexamen d''un refus discrétionnaire sans perdre l''avancement.","texte_reference":"Vous conservez +1 Diplomatie dans les rapports professionnels avec l’administration. Une fois par démarche, après un refus discrétionnaire ou une mauvaise orientation, vous obtenez le réexamen du dossier par un responsable compétent sans perdre l’avancement déjà acquis. Cela autorise une nouvelle tentative normalement interdite à situation identique ; un défaut de forme doit être corrigé. Le refus fondé sur une interdiction légale ne peut être contourné ainsi.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'requisition_de_service', 'Réquisition de service', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"Pour une mission, un moyen en plus : véhicule de service, local, ou lot matériel jusqu''à 10 000 $.","texte_reference":"Pour une mission autorisée, vous pouvez obtenir un moyen supplémentaire disponible : voiture ou utilitaire de service, local utilisable, ou lot matériel d’une valeur maximale de 10 000 $. Un seul moyen est réquisitionné par ce talent à la fois, jusqu’à la fin de la mission. L’affectation ne nécessite pas de négociation de faveur. Le moyen doit exister, pouvoir être confié à votre fonction et être restitué ; conducteur ou spécialiste ne sont pas fournis automatiquement.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'couverture_fonctionnelle', 'Couverture fonctionnelle', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"1/scénario, l''institution étouffe les suites d''une infraction défendable dans son ressort. Le MJ dit d''abord si l''affaire est couverte.","texte_reference":"Une fois par scénario, votre institution peut étouffer les conséquences institutionnelles d’une infraction défendable commise pendant une opération ou qu’elle a intérêt à couvrir. Elle fait classer la procédure ordinaire dans son ressort, tolère une initiative irrégulière ou écarte un élément compromettant qu’elle contrôle. Le bénéfice est effectif, sans nouveau jet pour convaincre le protecteur après validation du périmètre. Il ne réécrit ni les faits ni toutes les preuves détenues par des tiers ; une affaire publiquement indéfendable, une trahison ou un acte que l’institution refuse fondamentalement de couvrir reste hors de portée. Le MJ annonce si l’affaire est couverte avant consommation du bénéfice.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'dossier_institutionnel', 'Dossier institutionnel', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"Une identité de couverture officielle, entretenue par l''administration.","texte_reference":"Vous disposez d’une identité opérationnelle de couverture entretenue par l’administration, avec les pièces et inscriptions officielles correspondant à une profession ou affectation plausible. Les vérifications ordinaires auprès des organismes couverts confirment cette identité sans remonter automatiquement à votre identité réelle. Une seule couverture est active par ce talent. Le service peut la remplacer entre deux opérations si elle est abandonnée ou compromise ; la nouvelle couverture ne change pas votre visage, vos compétences ni les traces déjà découvertes. Elle ne confère pas d’elle-même les accès secrets d’Habilitation administrative et d’Accès aux registres.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'autorite_officielle', 'Autorité officielle', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"+2 Autorité pour un ordre qui entre dans tes prérogatives d''agent assermenté.","texte_reference":"+2 Autorité lorsqu’un agent assermenté donne un ordre entrant réellement dans ses prérogatives.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'priorite_interservices', 'Priorité interservices', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"1/scénario, deux services s''engagent ensemble sur une opération locale précise (liaison, moyens, délai annoncés).","texte_reference":"Une fois par scénario, vous pouvez obtenir l’engagement coordonné de votre service et d’un autre service compétent sur une opération locale précise. Le résultat doit prendre une forme concrète : sécurisation d’un accès, évacuation, contrôle d’un périmètre, prise en charge de victimes ou autre intervention dans leurs attributions. Un responsable de liaison, un objectif, les moyens engagés et un délai sont annoncés. La rivalité administrative ne peut suffire à refuser. Les agents agissent selon leur hiérarchie et résolvent normalement les dangers ; vous n’obtenez pas un commandement général sur eux ni la neutralisation automatique de toute opposition.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'appui_du_service', 'Appui du service', NULL, '{"nature":"realite","categorie":"sphere","milieu":"gouvernementale","cout_xp":10,"texte_court":"1/scénario, un spécialiste ou une équipe de trois agents est affecté à une tâche. Ils font leurs propres tests.","texte_reference":"Une fois par scénario, pour une mission autorisée, vous choisissez l’affectation d’un spécialiste pour une tâche d’expertise, ou d’une petite équipe de trois agents pour une tâche de terrain relevant de votre service. Leur fonction, leur profil, leur équipement courant et leur délai sont connus avant engagement. Ils peuvent analyser une pièce, surveiller un accès, sécuriser une position, accompagner un transfert ou intervenir techniquement ; ils effectuent leurs propres tests si la tâche est contestée ou dangereuse. L’affectation dure le temps de cette tâche, pas toute la campagne. Une expertise ordinaire matériellement réalisable donne ses conclusions, pas seulement le nom d’un autre interlocuteur.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'protection', 'Protection', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"1/scène : si ta Renommée (ou celle de ton organisation) dépasse celle des adversaires, une intimidation ou une hostilité limitée cesse et tu peux te retirer, sans jet.","texte_reference":"Une fois par scène, lors d’une confrontation où les adversaires peuvent encore choisir de reculer, vous pouvez faire valoir une affiliation criminelle réelle et crédible. Comparez leur Renommée pertinente à la meilleure entre votre Renommée et celle de votre organisation dans ce territoire ; elles ne s’additionnent pas. Si votre valeur est supérieure, un adversaire ou petit groupe qui reconnaît cette protection doit abandonner une intimidation, un racket ou une hostilité limitée et vous laisser vous retirer, sans jet. Face à une Renommée égale ou supérieure, la confrontation se résout normalement ; la réputation invoquée peut fournir la circonstance pertinente. Le talent ne soumet pas une faction en guerre ouverte à votre organisation, ne fait pas oublier une vendetta majeure et ne retire pas des actions de combat à une cible.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'marche_noir', 'Marché noir', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Offre ferme sur une marchandise illégale que ton organisation distribue : dans la journée si locale, trois jours si rare.","texte_reference":"Pour une marchandise illégale non unique et réellement distribuée dans les filières de votre organisation, vous obtenez une offre ferme et la fourniture du bien au prix annoncé, sans mission préalable uniquement destinée à trouver un vendeur ou gagner sa confiance. Un bien courant disponible localement peut être retiré dans la journée ; un bien rare commandable est livré avec un délai annoncé avant engagement : trois jours hors transport exceptionnel annoncé. Le circuit peut fournir un bien interdit au marché ordinaire, sans exiger les justificatifs de vente habituels ; cela ne lève pas les conditions physiques, techniques ou mécaniques nécessaires pour l’utiliser. Marché noir ne fixe pas une remise : Recéleur et Maître du Troc traitent les prix.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'receleur', 'Recéleur', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"+2 Commerce pour acheter ou vendre des marchandises volées ou illégales par ton réseau.","texte_reference":"+2 Commerce pour acheter/vendre des marchandises volées ou illégales via son réseau.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'blanchiment', 'Blanchiment', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Tu sais faire passer des revenus criminels par une filière légale, si tu as le réseau.","texte_reference":"Sait faire passer des revenus criminels par une filière légale lorsqu’il possède le réseau nécessaire.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'faussaires', 'Faussaires', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Accès à une filière de faux papiers.","texte_reference":"Accès à une filière de faux papiers, identités ou documents.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'dette_de_faveur', 'Dette de faveur', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Une faveur importante d''un débiteur nommé : un service sans jet ni paiement. Elle se reconstitue après un nouveau service rendu, jamais par le seul passage du temps.","texte_reference":"Vous disposez d’une faveur importante reconnue par un débiteur nommé, dont les moyens et les limites sont définis. L’appeler obtient un service qui demanderait normalement paiement, risque mesuré ou contrepartie, sans nouveau jet de persuasion ni paiement pour le service convenu : cacher temporairement une personne, prêter un véhicule pour une opération, fournir une information confidentielle possédée ou ouvrir une rencontre délicate. Le débiteur fournit le service ou un équivalent dans ses moyens ; il n’est pas tenu au suicide ou à une trahison fondamentale. La faveur est consommée lorsque la prestation est engagée. Après un nouveau service significatif rendu et reconnu, vous pouvez reconstituer une faveur active garantie par ce talent, sans rachat d’XP. Aucune recharge au seul changement de scénario.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'omerta', 'Omerta', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"+2 Force Mentale contre une pression pour trahir ton organisation ; ton cercle proche protège tes secrets et t''alerte. +4 au total avec Omerta familiale.","texte_reference":"Vous bénéficiez de +2 Force Mentale contre les pressions visant à vous faire trahir votre organisation. Votre cercle professionnel proche et coopérant organise aussi le silence : demandes banales sans réponse sur vos informations sensibles, et alerte en cas de demande ciblée dès qu’il peut vous prévenir. Exception explicite : lorsque le même test relève également d’Omerta familiale, les deux bonus se cumulent pour +4 au total. La relance une fois par scène d’Omerta familiale reste utilisable et bénéficie de ce total. Mental d’acier ne fournit pas un troisième bonus équivalent et aucun test ne bénéficie de plusieurs relances de talent. Trahison d’un associé, contrainte réelle et preuves extérieures restent possibles.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'planque', 'Planque', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Un refuge réel, lié à ton organisation.","texte_reference":"Dispose d’un refuge réellement existant associé à son organisation.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'homme_femme_du_milieu', 'Homme/Femme du milieu', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"+1 Diplomatie ou Autorité dans ton organisation ; 1/scénario, elle passe l''éponge sur un écart limité.","texte_reference":"Vous conservez +1 Diplomatie ou Autorité, choisi à l’acquisition, dans votre organisation. Une fois par scénario, elle passe l’éponge sur un écart limité que vous avez commis envers ses règles ou intérêts : négligence, initiative non autorisée, altercation interne mineure ou manquement comparable. La sanction interne normalement attendue est abandonnée, sans nouvelle dette automatique qui remplacerait simplement cette sanction. La faute doit rester réparable et l’organisation doit pouvoir assumer ce pardon ; trahison, pertes majeures ou attaque contre ses dirigeants restent hors de portée. Le pardon interne n’efface pas une procédure menée par une institution extérieure.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'armurier_du_milieu', 'Armurier du milieu', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Une arme prêtée, jusqu''à 5 000 $, échangeable entre deux missions. Munitions payantes.","texte_reference":"Votre organisation met à votre disposition une arme non unique de son catalogue disponible, sans prix d’achat, choisie pour l’opération. Vous pouvez la restituer et en changer à l’armurerie entre deux missions. Une seule arme de ce talent est sortie à la fois ; elle reste prêtée et n’est pas revendable. Son entretien courant est pris en charge. Le plafond de valeur est 5 000 $ ; les armes exigeant une installation, un équipage, un accès spécial ou un programme expérimental ne sont pas ouvertes automatiquement. Les munitions restent des consommables payés normalement.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'entreprise_de_couverture', 'Entreprise de couverture', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Une activité légale qui sert de façade.","texte_reference":"Possède ou utilise une activité légale pouvant servir de façade.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'corruption_locale', 'Corruption locale', NULL, '{"nature":"realite","categorie":"sphere","milieu":"mafieuse","cout_xp":10,"texte_court":"Un Contact compromis dans une institution précise, avec les moyens de son vrai poste.","texte_reference":"Un Contact compromis dans une institution précise ; ses capacités restent celles de son véritable poste.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'fiable', 'Fiable', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"+2 pour obtenir un contrat grâce à ta réputation ; 1/scénario, avance de 25 % sur un contrat financé.","texte_reference":"Vous conservez +2 pour obtenir un contrat grâce à votre réputation professionnelle. Une référence réelle et vérifiable rend ce bonus utilisable auprès d’un nouveau commanditaire. Une fois par scénario, sur un contrat accepté et financé, vous pouvez demander et obtenir une avance de 25 %, sans concession supplémentaire ; elle est déduite du solde. Elle n’est pas versée si vous ne la demandez pas et ne s’ajoute pas à une avance déjà au moins équivalente. Le contrat conserve ses obligations de justification ou de restitution en cas de non-exécution.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'bonnes_adresses', 'Bonnes adresses', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"+2 Investigation, Survie ou Commerce pour trouver un service clandestin là où tu as tes entrées.","texte_reference":"+2 Investigation, Survie ou Commerce pour trouver un service clandestin dans un milieu Crawler où il possède réellement des entrées.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'dans_le_coup', 'Dans le coup', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Tu connais les lieux et réseaux Neopunks de ta scène ; 1/scénario, un point de situation complet par le MJ (faits, rumeurs, contradictions).","texte_reference":"Vous connaissez les lieux de rencontre et réseaux Neopunks réellement implantés dans la scène que vous fréquentez, ainsi que l’actualité courante qui y circule. Une fois par scénario, vous pouvez demander au MJ un point de situation sur ce milieu, sans quota de questions : qui est banni ou influent, quel groupe monte, où joindre un relais, ou quels mouvements corporatifs connus pourraient le viser. Les réponses distinguent faits, rumeurs et informations encore contradictoires. Les connaissances ordinaires restent disponibles en permanence. Vous pouvez apprendre une menace signalée par le réseau, pas un plan absolument secret inconnu de tous. Connaître un refuge ne garantit pas d’y être accueilli : Nid de frelons fournit cet accueil.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'contact_de_renom', 'Contact de renom', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Un Contact Crawler notable. Son aide n''est jamais automatique.","texte_reference":"Un Contact Crawler notable. Son aide n’est jamais automatique.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'assurance_silver', 'Assurance Silver', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Couverture CareForce Silver gratuite.","texte_reference":"Attribue automatiquement une couverture CareForce Silver gratuite dans les Services/Train de vie.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'maitrise_des_codes_de_la_rue', 'Maîtrise des codes de la rue', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"+1 Langages & Argot (culture Crawler) ; en quelques minutes, tu sais qui fait autorité ici et quelle règle s''applique.","texte_reference":"Vous conservez +1 Langages & Argot sur la culture Crawler. Après quelques minutes d’observation et d’échanges dans une scène locale accessible, vous identifiez qui y fait réellement autorité, quelle règle de passage ou de respect s’applique et quel comportement risque de provoquer un incident. Ces conclusions portent sur les signes et usages visibles, non sur les intentions cachées. Elles donnent une manière appropriée d’aborder le milieu, pas son amitié automatique.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'optitech', 'OptiTech', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Avec outils et préparation, un matériel ignore sa première défaillance non catastrophique de la scène. Ni DGT ni Armure.","texte_reference":"Avec outils et préparation, optimise un matériel pour la scène : il ignore sa première défaillance matérielle non catastrophique.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'logifake', 'Logifake', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Un profil Logifate de couverture qui tient aux contrôles ordinaires.","texte_reference":"Possède un profil Logifate de couverture cohérent résistant aux contrôles ordinaires.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'nid_de_frelons', 'Nid de frelons', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Accueil discret dans une implantation Neopunk alliée, pour toi et deux compagnons, trois nuits par scénario au total.","texte_reference":"Dans une implantation Neopunk alliée réellement accessible, votre reconnaissance vous donne un accueil discret pour vous et jusqu’à deux compagnons, pendant trois nuits par scénario au total. Le refuge fournit couchage simple, relais de communication et alerte en cas de recherche visible, sans négociation de service à chaque arrivée. Il faut respecter ses règles et ne pas avoir trahi le réseau. Aucun refuge n’apparaît dans une zone dépourvue d’implantation. Changer de refuge ne réinitialise pas les trois nuits.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'insignifiant', 'Insignifiant', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"+2 Furtivité pour te fondre dans une foule ; on oublie ton visage après une interaction banale.","texte_reference":"+2 Furtivité pour se fondre dans une foule ; les témoins retiennent difficilement son visage après une interaction banale.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'fixweb', 'Fixweb', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Membre du réseau oral des Fixers : chercher ou faire circuler des contrats, joindre un intermédiaire local.","texte_reference":"Membre du réseau oral des Fixers ; peut rechercher ou faire circuler des contrats et contacter un intermédiaire local.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'black_clinic', 'Black Clinic', NULL, '{"nature":"realite","categorie":"sphere","milieu":"crawler","cout_xp":10,"texte_court":"Une clinique noire te soigne sans dossier ; urgence prioritaire, paiement en dette convenue.","texte_reference":"Une clinique noire ou un réseau Meditech nommé vous reçoit sans exiger de dossier institutionnel compatible. Les urgences bénéficient d’une prise en charge prioritaire selon la gravité, sans attendre une avance financière ; le règlement devient une dette convenue. Les soins ne sont pas automatiquement transmis à une institution extérieure. Honoraires, capacités médicales et risques matériels restent réels : ni implant gratuit, ni guérison impossible, ni effacement des preuves déjà existantes.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'communaute_de_fideles', 'Communauté de fidèles', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"1/scénario, ton réseau de fidèles rassemble en une journée observations et rumeurs sur une question concrète.","texte_reference":"Vous disposez d’un réseau local identifié de fidèles volontaires. Une fois par scénario, vous pouvez lui confier une question concrète sur une personne, un lieu ou une activité. En une journée, le réseau rassemble aussi bien les observations de ses membres que les rumeurs qu’ils ont entendues, sans que vous meniez chaque entretien. Il distingue ce qui a été vu, rapporté ou simplement supposé, et indique une provenance exploitable lorsque possible. Le talent peut ainsi faire remonter une information dont les fidèles ne sont pas les témoins directs ; il n’invente pas un secret qui ne circule nulle part et n’impose pas aux fidèles une infiltration dangereuse.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'autorite_religieuse', 'Autorité religieuse', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"+2 Autorité ou Diplomatie auprès des croyants qui reconnaissent ta fonction.","texte_reference":"+2 Autorité ou Diplomatie auprès de croyants reconnaissant réellement sa fonction.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'ministere', 'Ministère', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"Tu connais un domaine confidentiel de ta religion (exorcistes, reliques, ordres de Chasse…) et son canal ; +2 au premier test de Stress du scénario face à un phénomène de ce domaine.","texte_reference":"Vous connaissez un domaine confidentiel des activités de votre religion, choisi à l’acquisition : exorcistes, protection de reliques, ordres de Chasse présentés comme unités spécialisées, dossiers d’incidents ou dispositifs analogues. Vous savez qu’ils existent, comment reconnaître leurs principaux signes institutionnels et quel canal réel contacter pour leur signaler un cas ou leur poser une question. Vous connaissez une partie de leurs méthodes et explications profanes, pas automatiquement leurs pouvoirs ou la véritable nature des créatures. Cette préparation accorde +2 au premier test de Stress provoqué par la confrontation avec un phénomène correspondant à ce domaine, par scénario. Aucun passage automatique de Profane à Initié ni talent de Vérité n’est accordé.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'mission_ecclesiastique', 'Mission ecclésiastique', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"1/scénario, un mandat extérieur, avec lettre de mission et jusqu''à 1 000 $ de frais.","texte_reference":"Une fois par scénario, l’institution mandate une mission extérieure compatible avec votre rôle, y compris sur une proposition que vous lui soumettez. Elle fournit une lettre de mission et prend en charge jusqu’à 1 000 $ de frais justifiés de déplacement, hébergement et logistique, pour vous et vos accompagnants dans cette enveloppe commune. Le mandat donne une légitimité institutionnelle à votre présence ; il ne constitue ni immunité, ni droit d’entrée forcée, ni revenu personnel supplémentaire.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'hebergement_religieux', 'Hébergement religieux', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"Un espace durable pour toi et deux compagnons, avec rangement verrouillable.","texte_reference":"Une implantation réelle met durablement à votre disposition un espace simple pour vous et jusqu’à deux compagnons, avec rangement privatif verrouillable. Le logement et ses charges ordinaires sont pris en charge tant que le lien institutionnel est maintenu. La capacité convenue est réservée, et ne dépend pas chaque soir des places d’hospitalité restantes. Ce n’est ni une propriété revendable ni une planque secrète. Un loyer équivalent compté séparément est supprimé, sans hausse automatique du Train de vie.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'reseau_caritatif', 'Réseau caritatif', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"1/scénario : mise à l''abri de cinq personnes pendant sept jours, ou intégration à une opération humanitaire.","texte_reference":"Une fois par scénario, vous pouvez faire engager une opération caritative locale réelle, en choisissant l’un des deux usages suivants. Mise à l’abri : un moyen de transport accessible prend en charge jusqu’à cinq personnes en difficulté et les confie au réseau pour sept jours d’hébergement simple, de repas et de soins ordinaires disponibles. Couverture d’intervention : un convoi, une distribution ou un dispositif d’assistance réel vous intègre, avec jusqu’à deux compagnons aptes à y participer, pour rejoindre une zone ou des interlocuteurs accessibles à cette mission humanitaire. Le déplacement, le responsable et la mission sont annoncés ; il ne s’agit pas seulement d’une adresse d’association. Aucun blocus inviolable n’est franchi automatiquement, aucun accès secret n’est créé et l’opération doit rester compatible avec l’aide réellement fournie.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'education_theologique', 'Éducation théologique', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"+1 Savoirs (religion) ; 1/scène, dénoncer une contradiction d''une autorité religieuse devant ses fidèles : −3 à son Autorité fondée sur cette légitimité.","texte_reference":"Vous conservez +1 Savoirs sur religion, doctrine et histoire religieuse. Une fois par scène, devant des auditeurs reconnaissant la doctrine concernée, vous pouvez dénoncer une contradiction précise entre les actes ou ordres d’un interlocuteur et les obligations qu’il revendique. Sous pression, cela prend 1 PA et un test Esprit + Savoirs + 1d10e contre Charisme + Autorité + 1d10e de l’interlocuteur. En réussite, il subit −3 à ses tests d’Autorité fondés sur cette légitimité religieuse devant cet auditoire jusqu’à la fin de la scène. Les auditeurs restent libres de leurs convictions et peuvent le suivre pour d’autres raisons ; ses pouvoirs éventuels ne disparaissent pas. Une seule contestation réussie de ce talent est comptée contre la même légitimité dans la scène.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'conseiller_spirituel', 'Conseiller spirituel', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"+1 Diplomatie ; après 10 min de conseil, une personne pourra relancer un test de Stress raté face à l''épreuve préparée.","texte_reference":"Vous conservez +1 Diplomatie auprès d’une personne acceptant votre conseil. Après dix minutes d’échange réel sur une épreuve précise, elle peut relancer une fois un test de Stress raté face à cette épreuve avant la fin du scénario, hors échec narratif ; le second résultat est conservé. Une seule personne peut bénéficier à la fois de votre préparation, qui ne se cumule pas avec une autre relance du même test. Ni Trauma durable ni minima dus aux blessures ne sont supprimés.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'presence_holonet', 'Présence Holonet', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"+2 Investigation ou Représentation dans les médias officiels de ta religion.","texte_reference":"+2 Investigation ou Représentation dans les réseaux médiatiques officiels de sa religion.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'soutien_communautaire', 'Soutien communautaire', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"Mobiliser vite une aide profane modeste : bénévoles, repas, transport, traduction.","texte_reference":"Sait mobiliser rapidement une aide profane modeste : bénévoles, repas, transport, traduction, collecte…","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'ordre_religieux', 'Ordre religieux', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"Un correspondant spécialiste ; 1/scénario, une expertise prise en charge.","texte_reference":"L’Ordre vous attribue un correspondant spécialisé dans une discipline choisie et documentée. Une fois par scénario, vous obtenez une consultation ou expertise de cette discipline prise en charge : examen d’un dossier, diagnostic, analyse ou préparation professionnelle compatible. Le spécialiste accomplit le travail et fournit ses conclusions, avec ses propres tests si nécessaire. Entre les missions, il peut aussi assurer un enseignement cohérent. Aucun talent, rang ou point de Compétence n’est acquis gratuitement.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'reseau_confessionnel', 'Réseau confessionnel', NULL, '{"nature":"realite","categorie":"sphere","milieu":"religieuse","cout_xp":10,"texte_court":"Dans une implantation alliée, une recommandation vérifiable et un répondant local pour une première rencontre.","texte_reference":"Dans une implantation alliée existante où vous arrivez, le réseau vous fournit une recommandation vérifiable et un répondant local qui accepte une première rencontre. Celui-ci peut vous présenter à un interlocuteur pertinent de son environnement, y compris extérieur à votre religion, lorsqu’il dispose réellement de cette relation. La recommandation remplace l’absence de présentation et la méfiance liée au seul fait d’être inconnu ; elle ne garantit ni faveur, ni accord politique, ni ressources exceptionnelles.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'sommeil_leger', 'Sommeil léger', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"+2 Perception pour sentir un danger pendant le sommeil.","texte_reference":"+2 Perception pour remarquer un danger pendant le sommeil. Un danger évident réveille normalement le personnage.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'resistance_a_la_chaleur', 'Résistance à la chaleur', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"+2 Constitution contre la chaleur et la déshydratation.","texte_reference":"+2 Constitution contre chaleur, déshydratation et exposition climatique chaude.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'resistance_au_froid', 'Résistance au froid', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"+2 Constitution contre le froid.","texte_reference":"+2 Constitution contre froid et exposition climatique glaciale.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'sante_de_fer', 'Santé de fer', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"+2 Constitution contre maladies et infections ; +2 PV par 24 h de repos, après multiplicateurs.","texte_reference":"Vous bénéficiez de +2 Constitution contre les maladies et infections. Chaque période de 24 heures comportant le repos nécessaire vous rend 2 PV supplémentaires, ajoutés après les éventuels multiplicateurs de récupération. Ce bénéfice ne modifie ni vos PV maximum, ni les soins instantanés, ni les tests d’Agonie.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'insensibilite_a_la_douleur', 'Insensibilité à la douleur', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"La douleur seule ne gêne pas. À PV positifs, le Stress minimal des blessures compte un cran plus bas.","texte_reference":"La douleur seule n’impose ni malus ni interruption à une action que vous restez physiquement capable d’exécuter. Tant que vos PV sont positifs, calculez le Stress minimal imposé par vos blessures un cran moins sévèrement : Tendu devient Normal ; Paniqué devient Tendu. Un Stress psychologique indépendant reste applicable : retenez le plus grave des états encore imposés. Les blessures, incapacités réelles, l’Agonie et la mort ne changent pas.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'nageur', 'Nageur', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"+1 Athlétisme pour la nage ; pleine mobilité en eau ordinaire.","texte_reference":"+1 Athlétisme pour nage et manœuvres aquatiques ; pleine mobilité dans une eau ordinaire.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'ambidextre', 'Ambidextre', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"1/round, 1 PA : deux attaques à une main sur la même cible, deux jets à −3. Ni Viser, ni Rafale, ni Suppression.","texte_reference":"Vous utilisez indifféremment vos deux mains. Une fois par round, pendant votre activation, vous pouvez dépenser 1 PA pour une attaque double avec deux armes à une main que vous pouvez réellement manier : deux armes de contact ou deux armes à feu employées en tir simple. Déclarez une même cible pour les deux attaques, puis effectuez deux jets séparés, chacun avec −3. Chaque attaque réussie applique ses dégâts et l’Armure normalement ; les défenses se résolvent selon leurs règles ordinaires. L’attaque double ne bénéficie ni de Viser, ni de Rafale, ni de Suppression, et ne se déclenche pas pendant une riposte. Les autres attaques du round n’utilisent qu’une arme par PA. Aucune réserve de PA n’est augmentée.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'brave', 'Brave', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"+2 Maîtrise spirituelle face à la peur d''un danger physique identifiable.","texte_reference":"+2 Maîtrise spirituelle face à la peur d’un danger physique identifiable.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'fier_heritier', 'Fier héritier', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"Train de vie +1 cran, au moins Confortable ; seul accès au Luxe à la création.","texte_reference":"Augmente le Train de vie de base d’un cran, avec un minimum Confortable ; peut exceptionnellement faire passer Aisé à Luxe. Luxe n’est pas un niveau de départ ordinaire : ce talent constitue l’exception. Aucun versement libre n’est ajouté au Compte.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'renomme', 'Renommé', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"Renommée +1 dans ton milieu (maximum 5), non répétable.","texte_reference":"Votre Renommée augmente de 1 dans son milieu de référence, dans la limite de 5. Ce talent non répétable applique les bénéfices de la règle générale de Renommée. À 5, aucune progression supplémentaire ne peut être achetée avec ce talent.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'presence_remarquable', 'Présence remarquable', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"+2 au test social quand un trait frappant (beauté, voix, carrure…) est un vrai avantage.","texte_reference":"Choisir un trait particulièrement frappant : beauté, voix, allure, style, carrure… +2 au test social lorsque ce trait précis constitue réellement un avantage.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'apprentissage_fulgurant', 'Apprentissage fulgurant', NULL, '{"nature":"realite","categorie":"common","milieu":null,"cout_xp":10,"texte_court":"1/scénario, −2 XP sur une hausse de Compétence pratiquée pendant le scénario (minimum 1 XP).","texte_reference":"Une fois par scénario, réduit de 2 XP le coût d’une hausse de Compétence réellement pratiquée ou entraînée pendant ce scénario, minimum 1 XP.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'athlete', 'Athlète', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Athlétisme ; tu gagnes une égalité purement athlétique due à l''entraînement.","texte_reference":"+1 Athlétisme. En opposition purement athlétique, une égalité peut être départagée à son avantage lorsque l’entraînement constitue la différence.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'poings_de_fer', 'Poings de fer', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Pugilat ; mains nues DGT 2.","texte_reference":"+1 Pugilat. Les attaques à mains nues ont DGT 2 au lieu de 1.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'stabilite_augmentique', 'Stabilité augmentique', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Humanité aux tests ; Stress augmentique de base total −1.","texte_reference":"+1 Humanité. Le Stress augmentique de base total est réduit de 1, minimum 0.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'maitre_des_lames', 'Maître des lames', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Mêlée avec une lame ; sur marge 6+ et 1 PV infligé, une plaie : 2 PV par round jusqu''à une compression (1 PA) ou un soin.","texte_reference":"Vous bénéficiez de +1 aux tests de Mêlée avec une lame. Sur une attaque réussie avec marge 6+, infligeant au moins 1 PV à une cible capable de saigner, vous pouvez choisir une plaie persistante comme Altération. Elle fait perdre 2 PV à la fin du round suivant, puis de chaque round, jusqu’à une compression accessible de 1 PA ou un soin approprié. Une seule plaie de ce talent agit par cible. L’Armure n’est pas appliquée une seconde fois à cette perte de PV et aucune autre Altération gratuite n’est ajoutée.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'resistance_aux_toxines', 'Résistance aux toxines', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+2 Constitution contre poisons, drogues et toxines.","texte_reference":"+2 Constitution contre poisons, drogues, toxines et substances similaires.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'tireur_de_precision', 'Tireur de précision', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Tir ; 1/round, Viser gratuit avant un tir simple.","texte_reference":"Vous bénéficiez de +1 Tir. Une fois par round, juste avant un tir simple de votre activation, vous pouvez Viser sans dépenser le PA normalement requis. Cette visée apporte le +3 normal au tir concerné et les possibilités ordinaires de localisation si une Altération est obtenue. Le tir coûte toujours son PA. Une seconde visée sur ce même tir ne double pas le bonus ; pour d’autres tirs du round, Viser conserve son coût normal. Rafale, Suppression et l’attaque double d’Ambidextre restent incompatibles avec Viser. Le seuil normal d’Altération n’est pas abaissé.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'pilote_emerite', 'Pilote émérite', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Pilotage ; tu gagnes les égalités où la maîtrise du véhicule décide.","texte_reference":"+1 Pilotage. Gagne les égalités d’opposition lorsque la maîtrise du véhicule est réellement déterminante.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'ombre_vivante', 'Ombre vivante', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Furtivité ; +2 juste après avoir rompu la ligne de vue.","texte_reference":"+1 Furtivité. +2 lorsqu’il vient de rompre la ligne de vue et exploite immédiatement un environnement permettant de disparaître.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'reflexes_defensifs', 'Réflexes défensifs', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Esquive ; Défense active possible même Surpris (en payant son PA).","texte_reference":"Vous bénéficiez de +1 aux tests d’Esquive et pouvez effectuer une Défense active même en étant surpris. Vous payez normalement 1 PA et devez être physiquement capable de vous défendre. Si l’attaque ouvre le combat, ce PA est décompté de votre réserve du premier round. Le talent lève seulement l’interdiction liée à la Surprise : il ne donne aucun PA et n’autorise pas une défense interdite pour une autre raison. Le +1 aux tests ne recalcule pas la Défense passive.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'mains_lestes', 'Mains lestes', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Larcin ; +2 pour le pickpocket et la dissimulation d''un petit objet.","texte_reference":"+1 Larcin. +2 pour pickpocket, manipulation discrète ou dissimulation d’un petit objet.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'linguiste_emerite', 'Linguiste émérite', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Langages & Argot ; sens général d''une langue apparentée.","texte_reference":"+1 Langages & Argot. Peut déduire le sens général d’une langue inconnue apparentée à une langue connue.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'puits_de_savoir', 'Puits de savoir', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Savoirs ; dans un domaine choisi, rappel sans test et recherche deux fois plus rapide.","texte_reference":"Vous bénéficiez de +1 Savoirs et choisissez un grand domaine de connaissance. Dans ce domaine, les faits ordinaires que vous avez réellement appris sont rappelés sans test de mémoire. Lors d’une recherche spécialisée, votre travail personnel de lecture, comparaison et analyse demande deux fois moins de temps. L’accès aux documents, les délais externes et les tests nécessaires pour interpréter une question difficile restent inchangés.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'doc_de_choc', 'Doc de choc', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Soin ; Premiers soins réussis : +1 PV.","texte_reference":"+1 Soin. Les Premiers soins réussis rendent +1 PV supplémentaire.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'mecano_de_pointe', 'Mécano de pointe', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Mécanique ; diagnostic et démontage deux fois plus rapides.","texte_reference":"+1 Mécanique. Diagnostic, démontage et compréhension d’une machine accessible demandent environ deux fois moins de temps.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'detective', 'Détective', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Investigation ; sur DR 2+, un détail ou un lien de plus.","texte_reference":"+1 Investigation. Sur DR 2+, une enquête réussie révèle normalement un détail ou lien supplémentaire pertinent lorsque la scène en contient un.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'stable', 'Stable', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Maîtrise spirituelle aux tests de Stress ; 1/scène, l''aggravation d''un échec non narratif baisse d''un cran.","texte_reference":"Vous bénéficiez de +1 Maîtrise spirituelle aux tests de Stress. Une fois par scène, après un échec non narratif à un tel test, vous réduisez d’un cran l’aggravation qu’il devait provoquer, sans descendre sous votre état précédent. Normal → Tendu reste Normal ; Normal → Paniqué devient Tendu ; Tendu → Paniqué reste Tendu. Les autres conséquences de l’échec subsistent. Ce bénéfice ne modifie ni les minima dus aux blessures ni un état imposé sans test.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'sens_accru_x', 'Sens accru (X)', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+2 Perception quand le sens choisi est déterminant.","texte_reference":"Choisir vue, ouïe, odorat, toucher ou goût. +2 Perception lorsque ce sens précis est déterminant.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'maitre_de_la_survie', 'Maître de la survie', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Survie ; une collecte ou un abri réussi sert jusqu''à cinq personnes.","texte_reference":"Vous bénéficiez de +1 Survie. Une action réussie de collecte d’eau, de recherche de nourriture ou d’installation d’abri peut satisfaire jusqu’à cinq personnes, vous compris, sans multiplier les tests ni le temps consacré à cette même tâche par le nombre de bénéficiaires. Il doit réellement exister assez de ressources ou d’espace. Une collecte ne fournit pas simultanément les autres besoins qui n’ont pas été traités.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'mental_dacier', 'Mental d’acier', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Force Mentale ; +2 contre un interrogatoire ou une pression profane (garder le meilleur bonus).","texte_reference":"+1 Force Mentale. +2 contre interrogatoire, pression psychologique ou tentative profane de briser sa volonté ; prendre le meilleur bonus applicable.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'neurodriver', 'Neurodriver', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"Neurodive 1+ requis. +1 aux tests de Neurodive et +1 Neuroprogramme chargé ; ne change jamais le Rang.","texte_reference":"Prérequis Neurodive 1+. +1 aux tests de Neurodive et +1 Neuroprogramme chargé. Ne modifie jamais le Rang Neurodive.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'seducteur_seductrice', 'Séducteur / Séductrice', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Séduction ; tu distingues attirance sincère, indifférence et séduction intéressée.","texte_reference":"+1 Séduction. Après une interaction suffisamment longue et réussie, distingue généralement attirance sincère, indifférence et séduction intéressée.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'diplomate', 'Diplomate', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Diplomatie ; après quelques échanges, le MJ indique une concession praticable, ou qu''il n''y en a pas.","texte_reference":"Vous bénéficiez de +1 Diplomatie. Après quelques échanges réels, vous pouvez demander quelle concession concrète, garantie ou modification de proposition pourrait faire avancer la négociation, d’après les positions et indices exposés. Le MJ fournit une piste praticable, ou indique qu’aucun compromis ne ressort de ces échanges. Ce diagnostic ne révèle pas de pensée secrète : vous devez encore pouvoir offrir la concession et conclure l’accord.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'maitre_du_troc', 'Maître du Troc', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Commerce ; 5 points de remise à l''achat et de majoration à la vente, cumulables avec la négociation et Accès fournisseur.","texte_reference":"Vous bénéficiez de +1 Commerce. Lors d’un achat, vous obtenez 5 points de pourcentage supplémentaires de réduction sur le prix de référence de la transaction ; lors d’une vente, vous obtenez 5 points de pourcentage supplémentaires de majoration sur le prix de reprise de référence. Ce bénéfice est fixe, s’applique même si aucun jet n’est nécessaire et s’ajoute au résultat d’une négociation. Il se cumule aussi avec Accès fournisseur lorsqu’il s’applique : sa remise de statut et cet avantage de négociateur sont distincts. Les autres remises de statut équivalentes restent soumises à leur règle du meilleur bonus. Le talent ne crée ni acheteur ni obligation de conclure et ne multiplie pas son effet lorsqu’on fractionne la même transaction.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'artiste', 'Artiste', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Représentation ; une représentation réussie donne +3 à une interaction ultérieure qu''elle influence.","texte_reference":"+1 Représentation. Une représentation réussie peut créer une circonstance favorable (+3) lors d’une interaction ultérieure directement influencée.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent_realite', 'realite', 'autorite_naturelle', 'Autorité naturelle', NULL, '{"nature":"realite","categorie":"expertise","milieu":null,"cout_xp":10,"texte_court":"+1 Autorité ; +2 pour une consigne simple à un groupe qui te reconnaît déjà.","texte_reference":"+1 Autorité. +2 pour donner immédiatement une consigne simple à un groupe qui reconnaît déjà une légitimité au personnage.","lore":null,"statut_regle":"origine"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
